CREATE TABLE IF NOT EXISTS institutional_constitution_registry (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, document_title text NOT NULL, document_type text NOT NULL, version text, approval_status text NOT NULL DEFAULT 'Draft', effective_date date, custodian_role text, supersedes_reference text, evidence_reference text, status text NOT NULL DEFAULT 'Active', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ownership_protections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, protection_title text NOT NULL, protection_type text NOT NULL, protected_party text, trigger_event text, approval_requirement text, anti_dilution_principle text, transfer_restriction text, evidence_reference text, status text NOT NULL DEFAULT 'Draft', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS institutional_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, decision_title text NOT NULL, decision_class text NOT NULL, decision_owner text, authority_source text, status text NOT NULL DEFAULT 'Pending', decision_date date, evidence_reference text, board_reportable boolean NOT NULL DEFAULT false, reserved_matter boolean NOT NULL DEFAULT false, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS governance_health_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, snapshot_date date NOT NULL DEFAULT CURRENT_DATE, governance_score numeric, financial_control_score numeric, risk_score numeric, compliance_score numeric, procurement_score numeric, audit_score numeric, ownership_protection_score numeric, overall_status text NOT NULL DEFAULT 'Not Assessed', methodology_reference text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS governance_command_controls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, control_name text NOT NULL, control_level text NOT NULL DEFAULT 'Critical', control_description text NOT NULL, evidence_required text, owner_role text, escalation_route text, status text NOT NULL DEFAULT 'Active');
