INSERT INTO institutional_constitution_registry(entity_name,document_title,document_type,version,approval_status,custodian_role,status) SELECT 'OSANVAULT AFRICA LTD','Institutional Constitution Registry','Constitutional / governance document','To be confirmed','Not Yet Adopted','Company Secretary','Active' WHERE NOT EXISTS (SELECT 1 FROM institutional_constitution_registry WHERE document_title='Institutional Constitution Registry');
INSERT INTO ownership_protections(entity_name,protection_title,protection_type,status,notes) SELECT 'OSANVAULT AFRICA LTD','Founding / Indigenous Ownership Safeguard Framework','Founding ownership and indigenous-rights protection','Draft','Framework placeholder only. No legal right, shareholding, land title or customary ownership is created by this record. Final protections require the constitution, shareholder agreements, applicable land/property law and qualified legal advice.' WHERE NOT EXISTS (SELECT 1 FROM ownership_protections WHERE protection_title='Founding / Indigenous Ownership Safeguard Framework');
INSERT INTO governance_command_controls(entity_name,control_name,control_level,control_description,evidence_required,owner_role,escalation_route) SELECT 'OSANVAULT AFRICA LTD','Constitutional supremacy','Critical','Material corporate actions must be tested against the adopted constitution, applicable law, shareholder rights and reserved matters before execution.','Constitution, board/shareholder resolution, legal review and decision evidence','Company Secretary / Legal','Board / Shareholders as applicable' WHERE NOT EXISTS (SELECT 1 FROM governance_command_controls WHERE control_name='Constitutional supremacy');
INSERT INTO governance_command_controls(entity_name,control_name,control_level,control_description,evidence_required,owner_role,escalation_route) SELECT 'OSANVAULT AFRICA LTD','Ownership protection review','Critical','Transactions that could dilute, transfer or materially impair protected founding or indigenous interests must pass the defined protection and consent route.','Ownership register, protection instrument, consent evidence and legal review','Company Secretary / Board','Board / Shareholders / protected parties as legally defined' WHERE NOT EXISTS (SELECT 1 FROM governance_command_controls WHERE control_name='Ownership protection review');
INSERT INTO governance_command_controls(entity_name,control_name,control_level,control_description,evidence_required,owner_role,escalation_route) SELECT 'OSANVAULT AFRICA LTD','Executive institutional health review','High','Executive leadership should periodically review governance, finance, risk, compliance, procurement, audit and ownership-control indicators together.','Health snapshot, exceptions, decisions and action register','CEO / Board Secretariat','Board / relevant committee' WHERE NOT EXISTS (SELECT 1 FROM governance_command_controls WHERE control_name='Executive institutional health review');
INSERT INTO governance_command_controls(entity_name,control_name,control_level,control_description,evidence_required,owner_role,escalation_route) SELECT 'OSANVAULT AFRICA LTD','Reserved-matter gate','Critical','Reserved matters cannot proceed through ordinary delegated authority; the correct board/shareholder route must be evidenced before execution.','Delegated Authority Matrix, resolution and execution evidence','Company Secretary','Board / Shareholders' WHERE NOT EXISTS (SELECT 1 FROM governance_command_controls WHERE control_name='Reserved-matter gate');